ROOT = pathlib.Path(__file__).resolve().parent.parent / 'src' / 'i18n'


def js(s: str) -> str:
    return "'" + s.replace('\\', '\\\\').replace("'", "\\'") + "'"


def main() -> None:
    import subprocess
    keys = json.loads(subprocess.check_output(['node', str(ROOT.parent.parent / 'scripts' / 'i18n-check.mjs'), '--keys']))
    missing = [k for k in keys if k not in T]
    for idx, code in enumerate(['hi', 'ar', 'ms']):
        lines = ['// Generated by scripts/translations.py — edit the table there, then run it.',
                 'const strings: Record<string, string> = {']
        for k in keys:
            if k in T:
                lines.append(f'  {js(k)}: {js(T[k][idx])},')
        lines += ['};', '', 'export default strings;', '']
        (ROOT / f'{code}.ts').write_text('\n'.join(lines), encoding='utf-8')
    # placeholder sanity: every {var} in English must survive in each translation
    import re
    for k, vals in T.items():
        want = set(re.findall(r'\{\w+\}', k))
        for code, v in zip(['hi', 'ar', 'ms'], vals):
            if set(re.findall(r'\{\w+\}', v)) != want:
                print(f'placeholder mismatch [{code}]: {k!r}')
    print(f'{len(keys)} keys, {len(keys) - len(missing)} translated' + (f'; missing: {missing}' if missing else ''))


if __name__ == '__main__':
    main()
